<h1>درخواست مشاوره</h1><section class="card"><h2><?= $this->h($booking['mentor_name']) ?></h2><p>درخواست‌کننده: <?= $this->h($booking['user_name']) ?></p><p>وضعیت: <?= $this->status($booking['state']) ?></p><time data-timestamp="<?= (int)$booking['starts_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$booking['starts_at'])) ?> UTC</time><p class="prose"><?= nl2br($this->h($booking['problem'])) ?></p>
<?= $this->start('/booking/action') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><label>عملیات<select name="action"><option value="accept">پذیرش (مرشد / مدیر)</option><option value="reject">رد (مرشد / مدیر)</option><option value="cancel">لغو پیش از شروع</option><option value="complete">بستن جلسه پس از پایان</option></select></label><?= $this->field('note','توضیح','text','',false) ?><button>ثبت عملیات</button></form></section>
<?php if(!$admin): ?><p class="section"><a class="primary" href="<?= $this->h($this->url('/session?id='.$booking['id'])) ?>">جلسه متنی و آرشیو خصوصی</a></p><section class="card section"><h2>پیشنهاد تغییر زمان</h2><p>زمان قطعی قبلی تا تأیید طرف مقابل حفظ می‌شود. روز و ساعت پیشنهادی باید در برنامه آزاد مرشد باشد.</p><?= $this->start('/booking/propose') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><?= $this->field('starts_local','روز و ساعت جدید به وقت تهران','datetime-local') ?><button>ارسال پیشنهاد</button></form></section><?php endif; ?>
<?php foreach($proposals as $p): ?><article class="card section"><h3>پیشنهاد زمان</h3><time data-timestamp="<?= (int)$p['starts_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$p['starts_at'])) ?> UTC</time><p><?= $this->status($p['state']) ?></p><?php if(!$admin&&$p['state']==='pending'&&$p['proposer_id']!==$this->actor['user_id']): ?><?= $this->start('/booking/answer') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><input type="hidden" name="proposal_id" value="<?= $this->h($p['id']) ?>"><button name="accept" value="1">پذیرش زمان جدید</button><button class="secondary" name="accept" value="0">رد پیشنهاد</button></form><?php endif; ?></article><?php endforeach; ?>
<?php if(!$admin&&$booking['state']==='completed'&&$booking['user_id']===$this->actor['user_id']): ?><section class="card section"><h2>بازخورد خصوصی</h2><?= $this->start('/feedback') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><label>امتیاز<select name="score"><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>"><?= $i ?></option><?php endfor; ?></select></label><label>نظر<textarea name="body"><?= $this->val('body') ?></textarea></label><button>ثبت بازخورد</button></form></section><?php endif; ?>
<section class="card section"><h2>تاریخچه تصمیم‌ها</h2><?php foreach($events as $e): ?><p><?= $this->h($e['event']) ?> · <?= $this->h($e['note']) ?> <time data-timestamp="<?= (int)$e['created_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$e['created_at'])) ?></time></p><?php endforeach; ?></section>
